/// <reference types="astro/client" />
/// <reference path="../.astro/types.d.ts" />
/// <reference path="../worker-configuration.d.ts" />
// worker-configuration.d.ts is generated by `npm run types` (wrangler types, from wrangler.jsonc + .dev.vars.example):
// it declares the global `Env` / `Cloudflare.Env` (DB, MEDIA, BACKUPS, LOGIN_MAIL, ASSETS, vars, secret names) and
// the Workers runtime types. Regenerate it after changing bindings or vars.

declare namespace App {
  interface Locals {
    /** Set by src/middleware.ts on every signed-in admin request. */
    admin?: {
      email: string;
      role: 'owner' | 'helper';
    };
  }
}

/** Build facts baked in by astro.config.mjs (vite.define) for /build.json. */
declare const __BEEZY_BUILD_INFO__: {
  builtAt: string;
  commit: string | null;
  source: 'snapshot' | 'file' | 'remote';
};
